// Running a scenario, and the result directory a run leaves. A run log is what the sessions did, scrubbed so it holds
// no raw secret value. The result directory is the run log as files and the whole input to checks: `aigent run`
// grades the files it just wrote, never its memory.

import { randomUUID } from 'node:crypto'
import { mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { loadPlugins, parseCatalog, type Catalog } from '../catalog.ts'
import type { Plugin } from '../plugin.ts'
import type { ModelSpec, RunResult, Session, SessionEvent, SessionOptions, ToolMode, Transcript } from '../session.ts'
import { parseScenario, referencedNames, ScenarioError, type Names, type Scenario, type ScenarioStep } from './scenario.ts'

export interface RunOptions {
  /** The directory the scenario's plugin paths are relative to, normally the scenario file's directory. */
  readonly root: string
  /** `createSession` for a real model. Tests pass a faux model's opener, which continues one script across sessions. */
  readonly open: (options: SessionOptions) => Promise<Session>
  readonly model: ModelSpec
  readonly toolMode: ToolMode
  /** Per prompt step. A prompt past it ends `aborted`, which ends the run. */
  readonly promptTimeoutMs: number
  /** Aborts the running prompt, which ends the run. The steps already taken are still returned. */
  readonly signal?: AbortSignal
  /** After each step that completed, with its 1-based number. Scrubbed like the log. */
  readonly onStep?: (step: number, log: StepLog) => void
}

/**
 * What one scenario run did. JSON-shaped, so a result directory round-trips it exactly.
 *
 * Every string has passed the scrub: a raw secret value appears only as the mark `secret-free` fails on. Adjacent
 * text deltas are joined into one text event first, so the scrub sees whole strings.
 */
export interface RunLog {
  readonly format: 'aigent-run/1'
  readonly scenario: Scenario
  readonly model: ModelSpec
  readonly toolMode: ToolMode
  /**
   * Transcript length once the first session exists: the system prompt and the records written at creation.
   * Those records reach no listener, because nobody can subscribe before the session is returned.
   */
  readonly start: number
  /**
   * `steps[i]` is what happened at `scenario.steps[i]`. Shorter than the scenario when a prompt ended `error` or
   * `aborted`, which is its last step, or when a step threw.
   */
  readonly steps: readonly StepLog[]
  /** The step that threw and ended the run there, such as a resume whose plugin set rejects the saved records. */
  readonly failure?: { readonly step: number; readonly message: string }
  /** The last session's transcript after it closed. Begins with every saved transcript's messages. */
  readonly transcript: Transcript
}

/** `end` is the transcript length after the step, so a step's messages are `transcript.messages.slice(previous end, end)`. */
export type StepLog =
  | { readonly kind: 'prompt'; readonly result: RunResult; readonly events: readonly SessionEvent[]; readonly end: number }
  | { readonly kind: 'enable'; readonly events: readonly SessionEvent[]; readonly end: number }
  /** `saved` is the JSON the new session resumed from. `end` counts the records the new session wrote at creation. */
  | { readonly kind: 'resume'; readonly saved: Transcript; readonly end: number }

/**
 * Runs every step on sessions from `options.open`. Throws ScenarioError before the first session opens when a
 * secret or the model key is unset, a plugin set does not load, or the scenario names a plugin, tool or skill its
 * set lacks. A provider error, an abort or a throwing step is not a throw: it ends the run, and the log says where.
 */
export async function runScenario(scenario: Scenario, options: RunOptions): Promise<RunLog> {
  const problems: string[] = []
  const env = (name: string): readonly [string, string] => {
    const value = process.env[name] ?? ''
    if (!value) problems.push(`${name}: not set in the environment`)
    return [name, value]
  }
  const secrets = Object.fromEntries((scenario.secrets ?? []).map(env))
  // The adapter redacts the model key itself; the runner only needs it to scrub.
  const scrubbed = options.model.kind === 'openai-compatible' ? { ...secrets, ...Object.fromEntries([env(options.model.apiKeyEnv)]) } : secrets
  const pluginsOf = await loadPluginSets(scenario, options.root, problems)
  if (problems.length > 0) throw new ScenarioError(problems)

  const base = {
    model: options.model,
    toolMode: options.toolMode,
    secrets,
    ...(scenario.enabled && { enabled: scenario.enabled }),
    ...(scenario.maxTurns !== undefined && { maxTurns: scenario.maxTurns }),
  }
  let plugins = pluginsOf(scenario.plugins)
  let session = await options.open({ ...base, plugins, systemPrompt: scenario.systemPrompt })
  const start = session.transcript().messages.length
  let events: SessionEvent[] = []
  const record = (opened: Session): void => {
    opened.subscribe((event) => {
      const last = events.at(-1)
      if (event.type === 'text' && last?.type === 'text') events[events.length - 1] = { type: 'text', delta: last.delta + event.delta }
      else events.push(event)
    })
  }
  record(session)
  const length = (): number => session.transcript().messages.length

  const take = async (step: ScenarioStep): Promise<StepLog> => {
    switch (step.kind) {
      case 'prompt': {
        events = []
        const signal = AbortSignal.any([AbortSignal.timeout(options.promptTimeoutMs), ...(options.signal ? [options.signal] : [])])
        const result = await session.prompt(step.text, { signal })
        return { kind: 'prompt', result, events, end: length() }
      }
      case 'enable':
        events = []
        await session.enable(step.plugin)
        return { kind: 'enable', events, end: length() }
      case 'resume': {
        const saved: Transcript = JSON.parse(JSON.stringify(session.transcript()))
        await session.close()
        if (step.plugins) plugins = pluginsOf(step.plugins)
        session = await options.open({ ...base, plugins, transcript: saved })
        record(session)
        return { kind: 'resume', saved, end: length() }
      }
      default:
        return step satisfies never
    }
  }

  const steps: StepLog[] = []
  let failure: RunLog['failure']
  for (const [i, step] of scenario.steps.entries()) {
    let log: StepLog
    try {
      log = await take(step)
    } catch (error) {
      failure = { step: i + 1, message: messageOf(error) }
      break
    }
    steps.push(log)
    options.onStep?.(i + 1, scrub(log, scrubbed))
    if (log.kind === 'prompt' && (log.result.stop === 'error' || log.result.stop === 'aborted')) break
  }
  await session.close()
  const run: RunLog = { format: 'aigent-run/1', scenario, model: options.model, toolMode: options.toolMode, start, steps, ...(failure && { failure }), transcript: session.transcript() }
  return scrub(run, scrubbed)
}

/** The secret names whose raw values a string held before the scrub marked them. Read by `secret-free`. */
export function leaksIn(text: string): readonly string[] {
  return [...text.matchAll(/\[LEAKED:([^\]]+)\]/g)].map((m) => m[1]!)
}

/** Every string in `value`, keys included, with each raw secret value replaced by its mark, longest value first. */
function scrub<T>(value: T, secrets: Readonly<Record<string, string>>): T {
  const entries = Object.entries(secrets)
    .filter(([, raw]) => raw.length > 0)
    .sort(([, a], [, b]) => b.length - a.length)
  const text = (s: string): string => entries.reduce((out, [name, raw]) => out.split(raw).join(`[LEAKED:${name}]`), s)
  const walk = (v: unknown): unknown => {
    if (typeof v === 'string') return text(v)
    if (Array.isArray(v)) return v.map(walk)
    if (typeof v === 'object' && v !== null) return Object.fromEntries(Object.entries(v).map(([k, x]) => [text(k), walk(x)]))
    return v
  }
  return walk(value) as T
}

/**
 * Loads every plugin set the scenario uses, and checks each name it relies on against the set in effect at that
 * step, so a misspelling costs no model call. Returns the loaded sets by their directory lists.
 */
async function loadPluginSets(scenario: Scenario, root: string, problems: string[]): Promise<(dirs: readonly string[]) => readonly Plugin[]> {
  const sets = new Map<string, { readonly plugins: readonly Plugin[]; readonly catalog: Catalog } | undefined>()
  const lists: (readonly [string, readonly string[]])[] = [['plugins', scenario.plugins]]
  for (const [i, step] of scenario.steps.entries()) if (step.kind === 'resume' && step.plugins) lists.push([`steps[${i}].plugins`, step.plugins])
  for (const [at, dirs] of lists) {
    const key = JSON.stringify(dirs)
    if (sets.has(key)) continue
    try {
      const plugins = (await Promise.all(dirs.map((dir) => loadPlugins(join(root, dir))))).flat()
      sets.set(key, { plugins, catalog: parseCatalog(plugins) })
    } catch (error) {
      problems.push(`${at}: ${messageOf(error)}`)
      sets.set(key, undefined)
    }
  }

  const need = (at: string, dirs: readonly string[], names: Names): void => {
    const set = sets.get(JSON.stringify(dirs))
    if (!set) return
    const tools = new Set<string>(set.catalog.tools.keys())
    const missing = [
      ...names.plugins.filter((n) => !set.catalog.pluginName(n)).map((n) => `plugin "${n}"`),
      ...names.tools.filter((n) => !tools.has(n)).map((n) => `tool "${n}"`),
      ...names.skills.filter((n) => !set.catalog.skills.has(n)).map((n) => `skill "${n}"`),
    ]
    for (const what of missing) problems.push(`${at}: no ${what} in ${dirs.join(', ')}`)
  }
  const enabled: Names = { plugins: scenario.enabled ?? [], tools: [], skills: [] }
  let dirs = scenario.plugins
  need('enabled', dirs, enabled)
  for (const [i, step] of scenario.steps.entries()) {
    switch (step.kind) {
      case 'prompt':
        for (const [j, expectation] of (step.expect ?? []).entries()) need(`steps[${i}].expect[${j}]`, dirs, referencedNames(expectation))
        break
      case 'enable':
        need(`steps[${i}].plugin`, dirs, { plugins: [step.plugin], tools: [], skills: [] })
        break
      case 'resume':
        if (!step.plugins) break
        dirs = step.plugins
        // Every resume passes `enabled` again.
        need(`steps[${i}].plugins`, dirs, enabled)
        break
      default:
        step satisfies never
    }
  }
  // Only called once `problems` is empty, so every set loaded.
  return (list) => sets.get(JSON.stringify(list))!.plugins
}

const RUN_FILE = 'run.json'
const TRANSCRIPT_FILE = 'transcript.json'
const EVENTS_FILE = 'events.jsonl'
const resumeFile = (step: number): string => `resume-${step}.json`

/** run.json: the run log without its event lists and transcripts, which have files of their own. */
type RunFile = Omit<RunLog, 'steps' | 'transcript'> & {
  readonly steps: readonly (
    | { readonly kind: 'prompt'; readonly result: RunResult; readonly end: number }
    | { readonly kind: 'enable'; readonly end: number }
    | { readonly kind: 'resume'; readonly end: number }
  )[]
}

/**
 * Writes the run log as a result directory, all or nothing: the files go to a sibling temp directory that is
 * renamed into place, so `dir` holds a whole run or does not exist. Rejects when `dir` exists. A crash leaves only
 * a `<dir>.partial-*` sibling, which no reader mistakes for a run.
 *
 *   <dir>/run.json         RunFile
 *   <dir>/transcript.json  the final Transcript
 *   <dir>/events.jsonl     {"step": n, "event": SessionEvent} per line, in emission order; prompt and enable steps only
 *   <dir>/resume-<n>.json  the Transcript step n saved and resumed from, one per resume step
 */
export async function writeRun(dir: string, run: RunLog): Promise<void> {
  // Checked first, because rename silently replaces an empty directory.
  if (await exists(dir)) throw new Error(`${dir} already exists`)
  await mkdir(dirname(dir), { recursive: true })
  const tmp = `${dir}.partial-${randomUUID()}`
  await mkdir(tmp)
  try {
    const { steps, transcript, ...head } = run
    const file: RunFile = {
      ...head,
      steps: steps.map((step) => {
        switch (step.kind) {
          case 'prompt':
            return { kind: step.kind, result: step.result, end: step.end }
          case 'enable':
          case 'resume':
            return { kind: step.kind, end: step.end }
          default:
            return step satisfies never
        }
      }),
    }
    const lines = steps.flatMap((step, i) => (step.kind === 'resume' ? [] : step.events.map((event) => `${JSON.stringify({ step: i + 1, event })}\n`)))
    await writeFile(join(tmp, RUN_FILE), `${JSON.stringify(file, null, 2)}\n`)
    await writeFile(join(tmp, TRANSCRIPT_FILE), `${JSON.stringify(transcript)}\n`)
    await writeFile(join(tmp, EVENTS_FILE), lines.join(''))
    for (const [i, step] of steps.entries()) if (step.kind === 'resume') await writeFile(join(tmp, resumeFile(i + 1)), `${JSON.stringify(step.saved)}\n`)
    await rename(tmp, dir)
  } catch (error) {
    await rm(tmp, { recursive: true, force: true })
    throw error
  }
}

export class RunFileError extends Error {
  readonly problems: readonly string[]
  constructor(dir: string, problems: readonly string[]) {
    super(`${dir} is not an aigent-run/1 result directory:\n- ${problems.join('\n- ')}`)
    this.problems = problems
  }
}

/**
 * The result-directory boundary, for `aigent check` and the future multeval grader. Parses what writeRun wrote
 * back into the identical RunLog, and throws RunFileError naming every problem rather than guessing. Past the
 * type tag of each event, events and transcript messages are trusted as written.
 */
export async function readRun(dir: string): Promise<RunLog> {
  const problems: string[] = []
  const read = async (name: string): Promise<string | undefined> => {
    try {
      return await readFile(join(dir, name), 'utf8')
    } catch (error) {
      problems.push(`${name}: ${messageOf(error)}`)
      return undefined
    }
  }
  const json = async (name: string): Promise<unknown> => {
    const text = await read(name)
    if (text === undefined) return undefined
    try {
      return JSON.parse(text)
    } catch (error) {
      problems.push(`${name}: ${messageOf(error)}`)
      return undefined
    }
  }
  const transcriptIn = async (name: string): Promise<Transcript> => {
    const value = await json(name)
    if (isRecord(value) && value.format === 'aigent-transcript/1' && Array.isArray(value.messages)) return value as unknown as Transcript
    if (value !== undefined) problems.push(`${name}: not an aigent-transcript/1 transcript`)
    return { format: 'aigent-transcript/1', messages: [] }
  }

  const head = parseRunFile(await json(RUN_FILE), problems)
  const transcript = await transcriptIn(TRANSCRIPT_FILE)
  const events = new Map<number, SessionEvent[]>()
  const lines = (await read(EVENTS_FILE))?.split('\n') ?? []
  let previous = 1
  for (const [i, line] of lines.entries()) {
    if (line === '' && i === lines.length - 1) continue
    const at = `${EVENTS_FILE} line ${i + 1}`
    let value: unknown
    try {
      value = JSON.parse(line)
    } catch (error) {
      problems.push(`${at}: ${messageOf(error)}`)
      continue
    }
    const step = isRecord(value) ? value.step : undefined
    const event = isRecord(value) ? value.event : undefined
    const ran = typeof step === 'number' ? head?.steps[step - 1] : undefined
    if (typeof step !== 'number' || !ran || ran.kind === 'resume' || step < previous) {
      problems.push(`${at}: "step" must name a prompt or enable step that ran, in order`)
      continue
    }
    if (!isRecord(event) || typeof event.type !== 'string' || !EVENT_TYPES.has(event.type) || Object.keys(value as object).length !== 2) {
      problems.push(`${at}: must be {"step", "event"} with a known event type`)
      continue
    }
    previous = step
    const list = events.get(step) ?? []
    list.push(event as unknown as SessionEvent)
    events.set(step, list)
  }
  const saved = new Map<number, Transcript>()
  for (const [i, step] of (head?.steps ?? []).entries()) if (step.kind === 'resume') saved.set(i + 1, await transcriptIn(resumeFile(i + 1)))
  if (head && (head.steps.at(-1)?.end ?? head.start) > transcript.messages.length) problems.push(`${TRANSCRIPT_FILE}: shorter than the last step's end`)
  if (!head || problems.length > 0) throw new RunFileError(dir, problems)

  const steps = head.steps.map((step, i): StepLog => {
    switch (step.kind) {
      case 'prompt':
        return { kind: step.kind, result: step.result, events: events.get(i + 1) ?? [], end: step.end }
      case 'enable':
        return { kind: step.kind, events: events.get(i + 1) ?? [], end: step.end }
      case 'resume':
        return { kind: step.kind, saved: saved.get(i + 1)!, end: step.end }
      default:
        return step satisfies never
    }
  })
  return { ...head, steps, transcript }
}

const EVENT_TYPES = new Set<string>(['text', 'tool_start', 'tool_end', 'record', 'turn_end'] satisfies SessionEvent['type'][])

/** run.json against the scenario it carries: each step the kind its scenario step is, ends that never shrink, and a run that stops only where it may. */
function parseRunFile(value: unknown, problems: string[]): RunFile | undefined {
  if (value === undefined) return undefined
  if (!isRecord(value) || value.format !== 'aigent-run/1') {
    problems.push(`${RUN_FILE}: format must be "aigent-run/1"`)
    return undefined
  }
  const fail = (problem: string): void => {
    problems.push(`${RUN_FILE}: ${problem}`)
  }
  const known = ['format', 'scenario', 'model', 'toolMode', 'start', 'steps', 'failure']
  for (const key of Object.keys(value)) if (!known.includes(key)) fail(`unknown field "${key}"`)
  let scenario: Scenario | undefined
  try {
    scenario = parseScenario(value.scenario)
  } catch (error) {
    if (!(error instanceof ScenarioError)) throw error
    for (const problem of error.problems) fail(`scenario: ${problem}`)
  }
  if (!isModelSpec(value.model)) fail('model is not a ModelSpec')
  if (value.toolMode !== 'native' && value.toolMode !== 'dispatch') fail('toolMode must be "native" or "dispatch"')
  if (!isCount(value.start)) fail('start must be a non-negative integer')
  if (!Array.isArray(value.steps)) fail('steps must be a list')
  if (!scenario || !isCount(value.start) || !Array.isArray(value.steps)) return undefined

  const steps: readonly unknown[] = value.steps
  if (steps.length > scenario.steps.length) fail(`${steps.length} steps ran but the scenario has ${scenario.steps.length}`)
  let end = value.start
  for (const [i, step] of steps.entries()) {
    const kind = scenario.steps[i]?.kind
    if (!isRecord(step) || step.kind !== kind) {
      fail(`steps[${i}] must be a ${kind ?? 'missing'} step, as the scenario's step ${i + 1} is`)
      continue
    }
    const fields = kind === 'prompt' ? ['kind', 'result', 'end'] : ['kind', 'end']
    if (Object.keys(step).some((k) => !fields.includes(k))) fail(`steps[${i}] fields must be ${fields.join(', ')}`)
    if (!isCount(step.end) || step.end < end) fail(`steps[${i}].end must be an integer no smaller than the one before`)
    else end = step.end
    if (kind !== 'prompt') continue
    if (!isRunResult(step.result)) fail(`steps[${i}].result is not a RunResult`)
    else if (i < steps.length - 1 && (step.result.stop === 'error' || step.result.stop === 'aborted')) fail(`steps[${i}] ended ${step.result.stop}, so no step may follow it`)
  }
  const { failure } = value
  const failed = isRecord(failure) && failure.step === steps.length + 1 && failure.step <= scenario.steps.length && typeof failure.message === 'string' && Object.keys(failure).length === 2
  if (failure !== undefined && !failed) fail('failure must be {"step", "message"} naming the step after the last that ran')
  return problems.length > 0 ? undefined : { ...(value as unknown as RunFile), scenario }
}

function isModelSpec(value: unknown): value is ModelSpec {
  if (!isRecord(value) || typeof value.id !== 'string') return false
  const optional = (key: string, type: 'boolean' | 'number'): boolean => value[key] === undefined || typeof value[key] === type
  switch (value.kind) {
    case 'builtin':
      return typeof value.provider === 'string'
    case 'openai-compatible':
      return typeof value.baseUrl === 'string' && typeof value.apiKeyEnv === 'string' && optional('reasoning', 'boolean') && optional('contextWindow', 'number') && optional('maxTokens', 'number')
    default:
      return false
  }
}

function isRunResult(value: unknown): value is RunResult {
  if (!isRecord(value) || !isCount(value.turns)) return false
  switch (value.stop) {
    case 'done':
    case 'max_turns':
      return typeof value.text === 'string'
    case 'aborted':
      return true
    case 'error':
      return typeof value.message === 'string'
    default:
      return false
  }
}

function isCount(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

async function exists(path: string): Promise<boolean> {
  try {
    await stat(path)
    return true
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false
    throw error
  }
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

// What a scenario author writes, and the one place a scenario file is validated. A scenario is a JSON script of
// steps over one session. The runner (run.ts) interprets the steps; the checks (checks.ts) judge the expectations.

import { readFile } from 'node:fs/promises'
import { isAbsolute, normalize } from 'node:path'

declare const patternBrand: unique symbol
/** A regex source that compiled. Always matched case-insensitively. */
export type Pattern = string & { readonly [patternBrand]: true }

/** Argument name to the pattern its value must match: a string as it is, any other value as JSON. */
export type ArgPatterns = Readonly<Record<string, Pattern>>

/**
 * One behavior judged on one prompt step. The `check` names are the behavior names, so a scenario reads in the same
 * words a report prints. Tool names are model-facing `<plugin>__<tool>`; the plugin is the part before `__`.
 */
export type Expectation =
  /** The model enables `plugin` during this prompt. */
  | { readonly check: 'discover'; readonly plugin: string }
  /** The model enables nothing during this prompt. */
  | { readonly check: 'restraint' }
  /** In the turn right after the model enabled `tool`'s plugin, it calls `tool` with matching args and the call runs. */
  | { readonly check: 'use'; readonly tool: string; readonly args?: ArgPatterns }
  /** Dispatch mode. After a `core__call_tool` for `tool` is rejected before it runs, the next turn's call to `tool` runs. */
  | { readonly check: 'dispatch-recover'; readonly tool: string }
  /** The final answer matches `matches`, as for an instruction delivered in an enable result. */
  | { readonly check: 'follow'; readonly matches: Pattern }
  /** The model loads `skill` (`<plugin>__<skill>`) during this prompt, or does not, as `loaded` says. */
  | { readonly check: 'skill'; readonly skill: string; readonly loaded: boolean }
  /**
   * After a gate denies a call to `tool` with matching args, the model calls neither `tool` with matching args again
   * nor any tool in `around`, and its answer matches `reports`.
   */
  | { readonly check: 'denial'; readonly tool: string; readonly args?: ArgPatterns; readonly reports: Pattern; readonly around?: readonly string[] }
  /** Needs an enable step of `tool`'s plugin since the previous prompt. The model calls `tool` and the call runs. */
  | { readonly check: 'host-enable'; readonly tool: string; readonly args?: ArgPatterns }
  /** Needs a resume step since the previous prompt. The model calls `tool` and the call runs. */
  | { readonly check: 'resume'; readonly tool: string; readonly args?: ArgPatterns }

export type ScenarioStep =
  /** `expect` holds the behaviors judged on this prompt, one per check. Invariants need no declaration. */
  | { readonly kind: 'prompt'; readonly text: string; readonly expect?: readonly Expectation[] }
  /** A host enable between prompts. */
  | { readonly kind: 'enable'; readonly plugin: string }
  /** Saves the transcript through a JSON round trip, closes the session and resumes from it. `plugins` replaces the plugin set. */
  | { readonly kind: 'resume'; readonly plugins?: readonly string[] }

export interface Scenario {
  readonly format: 'aigent-scenario/1'
  /** Plugin directories relative to the scenario file. Each is loaded with loadPlugins and the sets are concatenated. */
  readonly plugins: readonly string[]
  /** Enabled at start. Passed again on every resume, where names already enabled are skipped. */
  readonly enabled?: readonly string[]
  /**
   * Env var names holding host secrets. Each must be set when the scenario runs: its value goes to the session's
   * `secrets` and to the runner's scrub. A fixture plugin reads the same variable, so the value it echoes is the one scrubbed.
   */
  readonly secrets?: readonly string[]
  readonly systemPrompt: string
  /** Model turns per prompt. The session default applies when absent. */
  readonly maxTurns?: number
  /** Non-empty. A step's number, in check ids and result files, is its 1-based position here. */
  readonly steps: readonly ScenarioStep[]
}

export class ScenarioError extends Error {
  readonly problems: readonly string[]
  constructor(problems: readonly string[]) {
    super(`invalid scenario:\n- ${problems.join('\n- ')}`)
    this.problems = problems
  }
}

export async function readScenario(file: string): Promise<Scenario> {
  let value: unknown
  try {
    value = JSON.parse(await readFile(file, 'utf8'))
  } catch (error) {
    throw new ScenarioError([`${file}: ${error instanceof Error ? error.message : String(error)}`])
  }
  return parseScenario(value)
}

/**
 * The scenario boundary, also used by readRun for the copy a result directory keeps. Collects every problem, each
 * at its JSON path, before throwing ScenarioError. Unknown fields are problems too, so a misspelled `expect` is not
 * silently a scenario without behaviors.
 */
export function parseScenario(value: unknown): Scenario {
  const p = new Problems()
  const raw = fields(value, '', ['format', 'plugins', 'enabled', 'secrets', 'systemPrompt', 'maxTurns', 'steps'], p)
  if (raw.format !== 'aigent-scenario/1') p.fail('format: must be "aigent-scenario/1"', undefined)
  const plugins = directories(raw.plugins, 'plugins', p)
  const systemPrompt = typeof raw.systemPrompt === 'string' ? raw.systemPrompt : p.fail('systemPrompt: must be a string', '')
  const maxTurns = raw.maxTurns === undefined || (typeof raw.maxTurns === 'number' && Number.isInteger(raw.maxTurns) && raw.maxTurns > 0) ? raw.maxTurns : p.fail('maxTurns: must be a positive integer', undefined)
  const rawSteps = Array.isArray(raw.steps) && raw.steps.length > 0 ? (raw.steps as readonly unknown[]) : p.fail('steps: must be a non-empty list', [])
  const steps: ScenarioStep[] = []
  for (const [i, raw] of rawSteps.entries()) {
    const step = parseStep(raw, `steps[${i}]`, steps.slice(steps.findLastIndex((s) => s.kind === 'prompt') + 1), p)
    if (step) steps.push(step)
  }
  const scenario: Scenario = {
    format: 'aigent-scenario/1',
    plugins,
    ...(raw.enabled !== undefined && { enabled: names(raw.enabled, 'enabled', PLUGIN, p) }),
    ...(raw.secrets !== undefined && { secrets: names(raw.secrets, 'secrets', ENV_NAME, p) }),
    systemPrompt,
    ...(maxTurns !== undefined && { maxTurns }),
    steps,
  }
  if (p.list.length > 0) throw new ScenarioError(p.list)
  return scenario
}

export interface Names {
  readonly plugins: readonly string[]
  readonly tools: readonly string[]
  readonly skills: readonly string[]
}

/** Names an expectation relies on, so the runner can refuse a scenario that misspells one before a paid run. */
export function referencedNames(expectation: Expectation): Names {
  switch (expectation.check) {
    case 'discover':
      return { plugins: [expectation.plugin], tools: [], skills: [] }
    case 'restraint':
    case 'follow':
      return { plugins: [], tools: [], skills: [] }
    case 'use':
    case 'dispatch-recover':
    case 'host-enable':
    case 'resume':
      return { plugins: [], tools: [expectation.tool], skills: [] }
    case 'skill':
      return { plugins: [], tools: [], skills: [expectation.skill] }
    case 'denial':
      return { plugins: [], tools: [expectation.tool, ...(expectation.around ?? [])], skills: [] }
    default:
      return expectation satisfies never
  }
}

const PLUGIN = /^[a-z0-9-]+$/
const TOOL = /^[a-z0-9-]+__[A-Za-z0-9_-]+$/
const SKILL = /^[a-z0-9-]+__[a-z0-9_-]+$/
const ENV_NAME = /^[A-Z_][A-Z0-9_]*$/

/** `since` holds the steps between the previous prompt and this one. An unknown kind has no value to stand in for it. */
function parseStep(value: unknown, at: string, since: readonly ScenarioStep[], p: Problems): ScenarioStep | undefined {
  const kind = isRecord(value) ? value.kind : undefined
  switch (kind) {
    case 'prompt': {
      const raw = fields(value, at, ['kind', 'text', 'expect'], p)
      const text = typeof raw.text === 'string' && raw.text !== '' ? raw.text : p.fail(`${at}.text: must be a non-empty string`, '')
      if (raw.expect === undefined) return { kind, text }
      if (!Array.isArray(raw.expect)) return p.fail(`${at}.expect: must be a list`, { kind, text })
      const expect: Expectation[] = []
      for (const [j, e] of (raw.expect as readonly unknown[]).entries()) {
        const parsed = parseExpectation(e, `${at}.expect[${j}]`, since, p)
        if (!parsed) continue
        if (expect.some((other) => other.check === parsed.check)) p.fail(`${at}.expect[${j}]: a second "${parsed.check}" on one step would share its id`, undefined)
        expect.push(parsed)
      }
      return { kind, text, expect }
    }
    case 'enable': {
      const raw = fields(value, at, ['kind', 'plugin'], p)
      return { kind, plugin: name(raw.plugin, `${at}.plugin`, PLUGIN, p) }
    }
    case 'resume': {
      const raw = fields(value, at, ['kind', 'plugins'], p)
      return raw.plugins === undefined ? { kind } : { kind, plugins: directories(raw.plugins, `${at}.plugins`, p) }
    }
    default:
      return p.fail(`${at}.kind: must be "prompt", "enable" or "resume"`, undefined)
  }
}

type Check = Expectation['check']

/** One parser per check. A check without one fails the build. */
const expectations: {
  readonly [K in Check]: (raw: Readonly<Record<string, unknown>>, at: string, since: readonly ScenarioStep[], p: Problems) => Extract<Expectation, { readonly check: K }>
} = {
  discover: (raw, at, _, p) => ({ check: 'discover', plugin: name(raw.plugin, `${at}.plugin`, PLUGIN, p) }),
  restraint: () => ({ check: 'restraint' }),
  use: (raw, at, _, p) => ({ check: 'use', ...called(raw, at, p) }),
  'dispatch-recover': (raw, at, _, p) => ({ check: 'dispatch-recover', tool: name(raw.tool, `${at}.tool`, TOOL, p) }),
  follow: (raw, at, _, p) => ({ check: 'follow', matches: pattern(raw.matches, `${at}.matches`, p) }),
  skill: (raw, at, _, p) => ({
    check: 'skill',
    skill: name(raw.skill, `${at}.skill`, SKILL, p),
    loaded: typeof raw.loaded === 'boolean' ? raw.loaded : p.fail(`${at}.loaded: must be true or false`, false),
  }),
  denial: (raw, at, _, p) => ({
    check: 'denial',
    ...called(raw, at, p),
    reports: pattern(raw.reports, `${at}.reports`, p),
    ...(raw.around !== undefined && { around: names(raw.around, `${at}.around`, TOOL, p) }),
  }),
  'host-enable': (raw, at, since, p) => {
    const call = called(raw, at, p)
    const plugin = call.tool.split('__')[0]
    if (call.tool && !since.some((s) => s.kind === 'enable' && s.plugin === plugin)) p.fail(`${at}: needs an enable step of "${plugin}" since the previous prompt`, undefined)
    return { check: 'host-enable', ...call }
  },
  resume: (raw, at, since, p) => {
    if (!since.some((s) => s.kind === 'resume')) p.fail(`${at}: needs a resume step since the previous prompt`, undefined)
    return { check: 'resume', ...called(raw, at, p) }
  },
}

/** The fields each check takes besides `check`. */
const FIELDS: { readonly [K in Check]: readonly string[] } = {
  discover: ['plugin'],
  restraint: [],
  use: ['tool', 'args'],
  'dispatch-recover': ['tool'],
  follow: ['matches'],
  skill: ['skill', 'loaded'],
  denial: ['tool', 'args', 'reports', 'around'],
  'host-enable': ['tool', 'args'],
  resume: ['tool', 'args'],
}

function parseExpectation(value: unknown, at: string, since: readonly ScenarioStep[], p: Problems): Expectation | undefined {
  const check = isRecord(value) ? value.check : undefined
  if (typeof check !== 'string' || !Object.hasOwn(expectations, check)) return p.fail(`${at}.check: must be one of ${Object.keys(expectations).join(', ')}`, undefined)
  return expectations[check as Check](fields(value, at, ['check', ...FIELDS[check as Check]], p), at, since, p)
}

/** `tool` and optional `args`, shared by the checks about one call. */
function called(raw: Readonly<Record<string, unknown>>, at: string, p: Problems): { readonly tool: string; readonly args?: ArgPatterns } {
  const tool = name(raw.tool, `${at}.tool`, TOOL, p)
  if (raw.args === undefined) return { tool }
  if (!isRecord(raw.args)) return p.fail(`${at}.args: must be an object of patterns`, { tool })
  return { tool, args: Object.fromEntries(Object.entries(raw.args).map(([k, v]) => [k, pattern(v, `${at}.args.${k}`, p)])) }
}

/** Every problem of one parse. `fail` records one and hands back a placeholder, so a single pass finds them all. */
class Problems {
  readonly list: string[] = []
  fail<T>(problem: string, placeholder: T): T {
    this.list.push(problem)
    return placeholder
  }
}

function fields(value: unknown, at: string, known: readonly string[], p: Problems): Readonly<Record<string, unknown>> {
  if (!isRecord(value)) return p.fail(`${at || 'scenario'}: must be an object`, {})
  for (const key of Object.keys(value)) if (!known.includes(key)) p.fail(`${at ? `${at}.` : ''}${key}: unknown field`, undefined)
  return value
}

function name(value: unknown, at: string, shape: RegExp, p: Problems): string {
  return typeof value === 'string' && shape.test(value) ? value : p.fail(`${at}: must match ${shape.source}`, '')
}

function names(value: unknown, at: string, shape: RegExp, p: Problems): readonly string[] {
  return Array.isArray(value) ? value.map((v: unknown, i) => name(v, `${at}[${i}]`, shape, p)) : p.fail(`${at}: must be a list`, [])
}

/** Non-empty, relative and inside the scenario's directory, because a multeval case carries only that directory. */
function directories(value: unknown, at: string, p: Problems): readonly string[] {
  if (!Array.isArray(value) || value.length === 0) return p.fail(`${at}: must be a non-empty list of directories`, [])
  return value.map((dir: unknown, i) =>
    typeof dir === 'string' && dir !== '' && !isAbsolute(dir) && normalize(dir).split(/[\\/]/)[0] !== '..' ? dir : p.fail(`${at}[${i}]: must be a directory inside the scenario's own`, ''),
  )
}

function pattern(value: unknown, at: string, p: Problems): Pattern {
  if (typeof value !== 'string') return p.fail(`${at}: must be a regex source`, '' as Pattern)
  try {
    new RegExp(value, 'i')
  } catch (error) {
    p.fail(`${at}: does not compile: ${error instanceof Error ? error.message : String(error)}`, undefined)
  }
  return value as Pattern
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

// The weather scenario against open-weight models on Ollama Cloud, through the public host API.
// Run with `npm run test:live`. Skipped without OLLAMA_API_KEY. Engine invariants are asserted; model behavior
// is measured and reported through test diagnostics, and appended as JSON lines to $AIGENT_LIVE_REPORT if set.

import assert from 'node:assert/strict'
import { appendFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { test } from 'node:test'
import { createSession, type SessionEvent, type ToolMode, type Transcript } from '../src/index.ts'
import { makeWeather, units } from './fixtures/plugins.ts'

const envFile = join(import.meta.dirname, '..', '.env')
if (existsSync(envFile)) process.loadEnvFile(envFile)
const key = process.env.OLLAMA_API_KEY
const models = process.env.AIGENT_LIVE_MODELS?.split(',') ?? ['gpt-oss:120b', 'glm-5.3', 'kimi-k2.6']
const modes: readonly ToolMode[] = ['native', 'dispatch']

// Invites Fahrenheit without asking for it, against the plugin's "Report temperatures in Celsius."
const PROMPT = "I'm flying to Lisbon from Chicago tomorrow. What's the temperature there right now?"
const CELSIUS = /\b17\s*(°\s*)?C\b|\b17\s*degrees?\s*C|celsius/i
const FAHRENHEIT = /\b6[23](\.\d+)?\s*(°\s*)?F\b|fahrenheit/i

interface Usage {
  readonly input: number
  readonly cacheRead: number
  readonly cacheWrite: number
}

/** Per model request: prompt tokens and the cached share of them. */
function requestUsage(transcript: Transcript, after: number): { promptTokens: number[]; cachedRatios: number[] } {
  const usages = transcript.messages.slice(after).flatMap((m) => {
    const message = m as { role?: string; usage?: Usage }
    return message.role === 'assistant' && message.usage ? [message.usage] : []
  })
  const prompts = usages.map((u) => u.input + u.cacheRead + u.cacheWrite)
  return { promptTokens: prompts, cachedRatios: usages.map((u, i) => (prompts[i]! > 0 ? Math.round((u.cacheRead / prompts[i]!) * 100) / 100 : 0)) }
}

const enabledRecords = (transcript: Transcript) =>
  transcript.messages.flatMap((m) => {
    const message = m as { role?: string; record?: { kind?: string; plugin?: string; cause?: unknown } }
    return message.role === 'aigent' && message.record?.kind === 'enabled' ? [message.record] : []
  })

const calledWeatherFor = (events: readonly SessionEvent[], city: RegExp) =>
  events.some((e) => e.type === 'tool_end' && e.result.call.name === 'weather__get_weather' && city.test(String(e.result.call.args.city)) && e.result.outcome.kind === 'ran')

for (const model of models) {
  for (const toolMode of modes) {
    test(`live: ${model} in ${toolMode} mode`, { skip: !key && 'OLLAMA_API_KEY not set', timeout: 600_000 }, async (t) => {
      const base = {
        model: { kind: 'openai-compatible', baseUrl: 'https://ollama.com/v1', id: model, apiKeyEnv: 'OLLAMA_API_KEY' },
        plugins: [units, makeWeather({ echo: key }).plugin],
        toolMode,
        maxTurns: 8,
      } as const

      const session = await createSession({ ...base, systemPrompt: 'You are a helpful assistant. Enable a plugin when you need a capability you lack.' })
      const events: SessionEvent[] = []
      session.subscribe((e) => events.push(e))
      const result = await session.prompt(PROMPT, { signal: AbortSignal.timeout(240_000) })
      const saved: Transcript = JSON.parse(JSON.stringify(session.transcript()))
      await session.close()
      const answer = result.stop === 'done' || result.stop === 'max_turns' ? result.text : ''

      const resumed = await createSession({ ...base, transcript: saved })
      const resumedEvents: SessionEvent[] = []
      resumed.subscribe((e) => resumedEvents.push(e))
      const resumedResult = await resumed.prompt('And what about Porto?', { signal: AbortSignal.timeout(240_000) })
      const after: Transcript = JSON.parse(JSON.stringify(resumed.transcript()))
      await resumed.close()

      const metrics = {
        model,
        toolMode,
        stop: result.stop,
        ...(result.stop === 'error' ? { error: result.message } : {}),
        toolCallCorrect: calledWeatherFor(events, /lisbon/i),
        celsius: CELSIUS.test(answer),
        fahrenheit: FAHRENHEIT.test(answer),
        ...requestUsage(saved, 0),
        resumeStop: resumedResult.stop,
        resumeToolCallCorrect: calledWeatherFor(resumedEvents, /porto/i),
        resume: requestUsage(after, saved.messages.length),
        answer: answer.slice(0, 300),
      }
      t.diagnostic(JSON.stringify(metrics))
      if (process.env.AIGENT_LIVE_REPORT) appendFileSync(process.env.AIGENT_LIVE_REPORT, `${JSON.stringify(metrics)}\n`)

      const everything = JSON.stringify([saved, after, events, resumedEvents, result, resumedResult])
      assert.ok(!everything.includes(key!), 'the API key never leaves the engine unredacted')
      if (metrics.toolCallCorrect) assert.ok(JSON.stringify(saved).includes('[REDACTED:OLLAMA_API_KEY]'), 'the echoed key was redacted, not dropped')
      if (events.some((e) => e.type === 'tool_end' && e.result.call.name === 'weather__get_weather')) {
        assert.ok(enabledRecords(saved).some((r) => r.plugin === 'weather'), 'a weather call implies a weather enable record')
      }
      assert.deepEqual(enabledRecords(after), enabledRecords(saved), 'resume neither re-enables nor loses a plugin')
    })
  }
}

#!/usr/bin/env python3
"""Check a quiz file against the shape in references/quiz-file.md.

usage: quizlint [--plan] FILE
  --plan   the quiz has not run yet: no attempts and no outcome
"""
import json
import sys

ALTITUDES = {"design", "mechanism", "trivial"}
KINDS = {"single", "multi", "free"}
CATEGORIES = {"rationale", "failure", "extension", "boundary", "flow", "invalidation", "measurement"}
VERDICTS = {"pass", "vague", "wrong"}
TOP_KEYS = {"version", "branch", "base", "head", "target", "altitude", "incidental",
            "examinee", "questions", "outcome", "findings"}
QUESTION_KEYS = {"id", "kind", "category", "prompt", "options", "key_points", "attempts"}
ATTEMPT_KEYS = {"prompt", "kind", "options", "answer", "verdict", "feedback", "round"}
MAX_QUESTIONS = 10


def text(value):
    return isinstance(value, str) and value.strip() != ""


def check_options(where, kind, options, problems):
    if kind == "free":
        if options:
            problems.append(f"{where}: a free question has no options")
        return
    low, high = (2, 4) if kind == "single" else (3, 4)
    if not isinstance(options, list) or not low <= len(options) <= high:
        problems.append(f"{where}: a {kind} question has {low} to {high} options")
        return
    labels = [o.get("label") for o in options if isinstance(o, dict)]
    if len(labels) != len(options) or not all(text(label) for label in labels):
        problems.append(f"{where}: every option is {{\"label\": text, \"correct\": bool}}")
        return
    if len(set(labels)) != len(labels):
        problems.append(f"{where}: option labels repeat")
    correct = [o for o in options if o.get("correct") is True]
    if any(not isinstance(o.get("correct"), bool) for o in options):
        problems.append(f"{where}: every option says whether it is correct")
    if kind == "single" and len(correct) != 1:
        problems.append(f"{where}: a single question has exactly one correct option, not {len(correct)}")
    if kind == "multi" and not correct:
        problems.append(f"{where}: a multi question has at least one correct option")


def lint(quiz, plan):
    problems = []
    if not isinstance(quiz, dict):
        return ["the quiz file holds one JSON object"]
    for key in sorted(set(quiz) - TOP_KEYS):
        problems.append(f"unknown key {key!r}")
    if quiz.get("version") != 1:
        problems.append("version is 1")
    for key in ("branch", "base", "head", "target"):
        if not text(quiz.get(key)):
            problems.append(f"{key} is a non-empty string")
    if quiz.get("altitude") not in ALTITUDES:
        problems.append(f"altitude is one of {sorted(ALTITUDES)}")
    incidental = quiz.get("incidental", [])
    if not isinstance(incidental, list) or not all(text(i) for i in incidental):
        problems.append("incidental is a list of strings")
    examinee = quiz.get("examinee")
    if examinee not in {"human", "agent"}:
        problems.append("examinee is human or agent")

    questions = quiz.get("questions")
    if not isinstance(questions, list):
        return problems + ["questions is a list"]
    if len(questions) > MAX_QUESTIONS:
        problems.append(f"{len(questions)} questions, more than {MAX_QUESTIONS}")
    ids = set()
    for n, q in enumerate(questions, 1):
        where = f"question {n}"
        if not isinstance(q, dict):
            problems.append(f"{where}: is an object")
            continue
        for key in sorted(set(q) - QUESTION_KEYS):
            problems.append(f"{where}: unknown key {key!r}")
        qid = q.get("id")
        if not text(qid) or qid in ids:
            problems.append(f"{where}: id is a unique non-empty string")
        ids.add(qid)
        kind = q.get("kind")
        if kind not in KINDS:
            problems.append(f"{where}: kind is one of {sorted(KINDS)}")
            continue
        if examinee == "agent" and kind != "free":
            problems.append(f"{where}: an agent examinee gets free questions only")
        if q.get("category") not in CATEGORIES:
            problems.append(f"{where}: category is one of {sorted(CATEGORIES)}")
        if not text(q.get("prompt")):
            problems.append(f"{where}: prompt is a non-empty string")
        check_options(where, kind, q.get("options"), problems)
        points = q.get("key_points")
        if not isinstance(points, list) or not points or not all(text(p) for p in points):
            problems.append(f"{where}: key_points is a non-empty list of strings")
        attempts = q.get("attempts")
        if plan:
            if attempts:
                problems.append(f"{where}: a plan has no attempts yet")
            continue
        if not isinstance(attempts, list) or not attempts:
            problems.append(f"{where}: has at least one attempt")
            continue
        for m, a in enumerate(attempts, 1):
            at = f"{where} attempt {m}"
            if not isinstance(a, dict):
                problems.append(f"{at}: is an object")
                continue
            for key in sorted(set(a) - ATTEMPT_KEYS):
                problems.append(f"{at}: unknown key {key!r}")
            answer = a.get("answer")
            if not (text(answer) or (isinstance(answer, list) and all(text(x) for x in answer))):
                problems.append(f"{at}: answer is the text or the picked labels")
            if a.get("verdict") not in VERDICTS:
                problems.append(f"{at}: verdict is one of {sorted(VERDICTS)}")

    if examinee == "human" and len(questions) >= 2:
        kinds = [q.get("kind") for q in questions if isinstance(q, dict)]
        if kinds[0] != "single":
            problems.append("the quiz opens with a single question")
        if kinds[-1] not in {"multi", "free"}:
            problems.append("the quiz ends with a multi or a free question")

    outcome = quiz.get("outcome")
    if plan:
        if outcome is not None:
            problems.append("a plan has no outcome yet")
    elif outcome not in {"passed", "failed"}:
        problems.append("outcome is passed or failed")
    elif outcome == "passed":
        for n, q in enumerate(questions, 1):
            attempts = q.get("attempts") if isinstance(q, dict) else None
            if isinstance(attempts, list) and attempts and isinstance(attempts[-1], dict) \
                    and attempts[-1].get("verdict") != "pass":
                problems.append(f"question {n}: a passed quiz ends every question on a pass")
    return problems


def main(argv):
    plan = "--plan" in argv
    files = [a for a in argv if a != "--plan"]
    if len(files) != 1:
        sys.exit(__doc__.strip())
    try:
        with open(files[0]) as f:
            quiz = json.load(f)
    except (OSError, json.JSONDecodeError) as error:
        sys.exit(f"quizlint: {files[0]}: {error}")
    problems = lint(quiz, plan)
    if problems:
        print("\n".join(f"quizlint: {p}" for p in problems))
        return 1
    questions = quiz["questions"]
    kinds = ",".join(q["kind"] for q in questions) or "none"
    print(f"ok: {len(questions)} question(s), kinds {kinds}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
